export const partDefaults=type=>type==='netLabel'?{name:'NET1'}:type==='bluetooth'?{name:'CF-BLE-UART',baud:9600}:Object.fromEntries((PART_FIELDS[type]||[]).map(f=>[f.key,f.value]));
export function validatePartParameters(c){if(c.type==='bluetooth'&&!validNetName(c.params?.name))throw Error('Bluetooth cihaz adı geçersiz.');if(c.type==='netLabel'&&c.params?.side!==undefined&&!['left','right','top','bottom'].includes(c.params.side))throw Error('Net pin yönü geçersiz.');if(c.type==='netLabel'&&!validNetName(c.params?.name))throw Error('Net adı: 1–32 harf, rakam veya _ + . / -; boşluk yok.');if(c.type==='servo'&&(c.params?.minPulse??544)>=(c.params?.maxPulse??2400))throw Error('Servo darbe aralığı geçersiz.');for(const f of PART_FIELDS[c.type]||[]){const v=c.params?.[f.key];if(v!==undefined&&(f.options?!f.options.some(o=>o[0]===v):!Number.isFinite(v)||v<f.min||v>f.max||(f.step===1&&f.key!=='lux'&&!Number.isInteger(v))))throw Error(`${c.id}: ${f.label} aralık dışında.`);}}
